<?php
declare(strict_types=1); namespace App\Http\Controllers\Classrooms; use App\Http\Controllers\Controller; use App\Http\Requests\Classrooms\CopyClassroomRequest; use App\Models\{AcademicYear,Classroom}; use App\Services\Classrooms\ClassroomPromotionService; use Illuminate\Http\RedirectResponse; use Illuminate\View\View;
class ClassroomCopyController extends Controller {public function form():View{request()->user()->can('classrooms.copy-structure')?:abort(403);return view('classrooms.copy',['years'=>AcademicYear::latest('starts_at')->get(),'rooms'=>Classroom::with(['academicYear','gradeLevel'])->get()]);}public function preview(CopyClassroomRequest $r):View{return view('classrooms.copy-preview',['data'=>$r->validated(),'rooms'=>Classroom::whereKey($r->validated('classroom_ids'))->with(['academicYear','gradeLevel'])->get()]);}public function confirm(CopyClassroomRequest $r,ClassroomPromotionService $s):RedirectResponse{$result=$s->copy($r->user(),$r->integer('source_academic_year_id'),$r->integer('target_academic_year_id'),$r->validated('classroom_ids'),$r->boolean('copy_homeroom'));return redirect()->route('classrooms.index',['academic_year'=>$r->integer('target_academic_year_id')])->with('success',"{$result['made']} struktur rombel berhasil disalin; {$result['skipped']} dilewati.");}}
